def gemini_research_paper_analysis(source_type, model, source_url=None, content_text=None, file_id=None, title=None, authors=None, published_year=None, analysis_prompt=None, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0315000" if __import__("os").path.isdir("./environment_mix/0315000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow()
    now_iso = now.replace(microsecond=0).isoformat() + "Z"

    api_keys = _load("api_keys.json")
    tool_runs = _load("tool_runs.json")
    paper_analyses = _load("paper_analyses.json")

    # ambient auth
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
    if not active_keys:
        return _err("UNAUTHORIZED", "No active API key available for this request.")
    chosen = None
    for k in sorted(active_keys, key=lambda r: (str(r.get("workspace_id","")), str(r.get("id","")))):
        rpm = k.get("requests_per_minute_limit")
        drl = k.get("daily_request_limit")
        dul = k.get("daily_usd_limit")
        if not isinstance(rpm, int) or rpm < 1 or rpm > 6000:
            continue
        if not isinstance(drl, int) or drl < 0:
            continue
        if not (isinstance(dul, int) or isinstance(dul, float)) or dul < 0:
            continue
        chosen = k
        break
    if not chosen:
        return _err("UNAUTHORIZED", "No active API key with valid limits is available.")

    # validate inputs
    if source_type not in ("url", "text", "file"):
        return _err("VALIDATION_ERROR", "source_type must be one of: url, text, file.")
    if model != "gemini-1.5-flash":
        return _err("VALIDATION_ERROR", "model must be 'gemini-1.5-flash'.")
    if source_type == "url":
        if not isinstance(source_url, str) or not source_url.strip():
            return _err("VALIDATION_ERROR", "source_url is required when source_type='url'.")
    if source_type == "text":
        if not isinstance(content_text, str) or not content_text.strip():
            return _err("VALIDATION_ERROR", "content_text is required when source_type='text'.")
    if source_type == "file":
        if not isinstance(file_id, str) or not file_id.strip():
            return _err("VALIDATION_ERROR", "file_id is required when source_type='file'.")
    if title is not None and not isinstance(title, str):
        return _err("VALIDATION_ERROR", "title must be a string when provided.")
    if authors is not None:
        if not isinstance(authors, list) or any((not isinstance(a, str)) for a in authors):
            return _err("VALIDATION_ERROR", "authors must be an array of strings when provided.")
    if published_year is not None:
        if not isinstance(published_year, int) or published_year < 1800 or published_year > 2100:
            return _err("VALIDATION_ERROR", "published_year must be an integer between 1800 and 2100 when provided.")
    if analysis_prompt is not None and not isinstance(analysis_prompt, str):
        return _err("VALIDATION_ERROR", "analysis_prompt must be a string when provided.")

    api_key_id = chosen.get("id")
    workspace_id = chosen.get("workspace_id")
    if not api_key_id or not workspace_id:
        return _err("UNAUTHORIZED", "API key context could not be resolved.")

    # quota checks
    minute_ago = now - datetime.timedelta(minutes=1)
    day_start = datetime.datetime(now.year, now.month, now.day)

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    recent = 0
    daily = 0
    daily_cost = 0.0
    for tr in tool_runs:
        if not isinstance(tr, dict) or tr.get("api_key_id") != api_key_id:
            continue
        cat = _parse_dt(tr.get("created_at"))
        if not cat:
            continue
        if cat >= minute_ago:
            recent += 1
        if cat >= day_start:
            daily += 1
            try:
                daily_cost += float(tr.get("estimated_cost_usd", 0) or 0)
            except Exception:
                pass

    # Estimate cost: small fixed estimate for analysis
    next_cost = 0.02
    rpm_limit = chosen["requests_per_minute_limit"]
    daily_req_limit = chosen["daily_request_limit"]
    daily_usd_limit = float(chosen["daily_usd_limit"])

    would_exceed = (recent + 1 > rpm_limit) or (daily_req_limit != 0 and daily + 1 > daily_req_limit) or (daily_cost + next_cost > daily_usd_limit)
    if would_exceed:
        run_id = "tr_" + hashlib.sha256((api_key_id + now_iso + "gemini_research_paper_analysis").encode("utf-8")).hexdigest()[:24]
        existing_ids = {r.get("id") for r in tool_runs if isinstance(r, dict)}
        if run_id in existing_ids:
            run_id = "tr_" + hashlib.sha256((run_id + "x").encode("utf-8")).hexdigest()[:24]
        tr = {
            "id": run_id,
            "api_key_id": api_key_id,
            "workspace_id": workspace_id,
            "tool_name": "gemini_research_paper_analysis",
            "status": "failed",
            "request_payload": {
                "source_type": source_type, "source_url": source_url, "content_text": ("[omitted]" if source_type == "text" else None),
                "file_id": file_id, "title": title, "authors": authors, "published_year": published_year, "model": model,
                "analysis_prompt": analysis_prompt
            },
            "response_payload": None,
            "error_code": "quota_exceeded",
            "error_message": "Quota exceeded.",
            "upstream_provider": "google_gemini",
            "upstream_request_id": None,
            "estimated_cost_usd": 0.0,
            "started_at": now_iso,
            "completed_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        tool_runs.append(tr)
        _save("tool_runs.json", tool_runs)
        return _err("QUOTA_EXCEEDED", "Quota exceeded.", tool_run_id=run_id)

    # Determine content for hashing/caching without storing sensitive prompt/raw errors
    effective_text = None
    if source_type == "text":
        effective_text = content_text.strip()
    elif source_type == "url":
        effective_text = f"URL:{source_url.strip()}"
    else:
        effective_text = f"FILE:{file_id.strip()}"

    content_sha = hashlib.sha256(effective_text.encode("utf-8")).hexdigest()

    # cache by content_sha256 if exists and completed
    existing = None
    for pa in paper_analyses:
        if isinstance(pa, dict) and pa.get("content_sha256") == content_sha and pa.get("analysis_status") == "completed" and pa.get("analysis_output") is not None:
            existing = pa
            break

    # create tool_run running
    run_id = "tr_" + hashlib.sha256((api_key_id + now_iso + "gemini_research_paper_analysis").encode("utf-8")).hexdigest()[:24]
    existing_ids = {r.get("id") for r in tool_runs if isinstance(r, dict)}
    if run_id in existing_ids:
        run_id = "tr_" + hashlib.sha256((run_id + "x").encode("utf-8")).hexdigest()[:24]

    req_payload = {
        "source_type": source_type,
        "source_url": (source_url.strip() if isinstance(source_url, str) else None),
        # Avoid storing full paper text (PII/sensitive); store truncated marker only
        "content_text": ("[omitted]" if source_type == "text" else None),
        "file_id": (file_id.strip() if isinstance(file_id, str) else None),
        "title": title,
        "authors": authors,
        "published_year": published_year,
        "model": model,
        "analysis_prompt": analysis_prompt
    }

    tr = {
        "id": run_id,
        "api_key_id": api_key_id,
        "workspace_id": workspace_id,
        "tool_name": "gemini_research_paper_analysis",
        "status": "running",
        "request_payload": req_payload,
        "response_payload": None,
        "error_code": None,
        "error_message": None,
        "upstream_provider": "google_gemini",
        "upstream_request_id": None,
        "estimated_cost_usd": float(next_cost),
        "started_at": now_iso,
        "completed_at": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }
    tool_runs.append(tr)

    # create paper_analysis unique per tool_run_id
    pa_id = "pa_" + hashlib.sha256((run_id + content_sha).encode("utf-8")).hexdigest()[:24]
    existing_pa_ids = {r.get("id") for r in paper_analyses if isinstance(r, dict)}
    if pa_id in existing_pa_ids:
        pa_id = "pa_" + hashlib.sha256((pa_id + "x").encode("utf-8")).hexdigest()[:24]

    if existing:
        # idempotent-ish: reuse cached output but still create a new paper_analyses row is disallowed by unique(content_sha256) constraint.
        # Therefore, for cache hit, we attach analysis_output directly to tool_run and create a paper_analyses row referencing existing by content_sha256
        # but unique(content_sha256) would conflict. So we DO NOT create new with same content_sha256; instead, we clone without content_sha256.
        analysis_output = existing.get("analysis_output")
        token_usage = existing.get("token_usage")
        pa = {
            "id": pa_id,
            "tool_run_id": run_id,
            "source_type": source_type,
            "source_url": (source_url.strip() if source_type == "url" else None),
            "title": title or existing.get("title"),
            "authors": authors if authors is not None else existing.get("authors"),
            "published_year": published_year if published_year is not None else existing.get("published_year"),
            "content_text": None,
            "content_sha256": None,  # avoid uniqueness conflict
            "model": model,
            "analysis_status": "completed",
            "analysis_output": analysis_output,
            "token_usage": token_usage,
            "created_at": now_iso,
            "updated_at": now_iso
        }
    else:
        # generate synthetic structured analysis (offline)
        analysis_output = {
            "summary": (f"Offline analysis for source_type='{source_type}' using {model}."),
            "key_findings": [
                "This analysis is generated offline and does not reflect actual model inference.",
                "Use the output structure as a stable schema for downstream integration."
            ],
            "critique": {
                "strengths": ["Provides a consistent structured response.", "Includes caching hash for repeatability."],
                "weaknesses": ["Not derived from actual paper content.", "No real citations extracted."]
            },
            "context": {"prompt_used": (analysis_prompt[:200] if isinstance(analysis_prompt, str) else None)},
            "citations": []
        }
        token_usage = {"input_tokens": 0, "output_tokens": 0, "total_tokens": 0}
        pa = {
            "id": pa_id,
            "tool_run_id": run_id,
            "source_type": source_type,
            "source_url": (source_url.strip() if source_type == "url" else None),
            "title": title,
            "authors": authors,
            "published_year": published_year,
            "content_text": None,  # do not persist raw text
            "content_sha256": content_sha,
            "model": model,
            "analysis_status": "completed",
            "analysis_output": analysis_output,
            "token_usage": token_usage,
            "created_at": now_iso,
            "updated_at": now_iso
        }

    paper_analyses.append(pa)

    # finalize tool_run succeeded
    response = {
        "tool_run_id": run_id,
        "paper_analysis": pa,
    }
    tr["status"] = "succeeded"
    tr["response_payload"] = response
    tr["completed_at"] = now_iso
    tr["updated_at"] = now_iso

    chosen["last_used_at"] = now_iso
    chosen["updated_at"] = now_iso

    _save("tool_runs.json", tool_runs)
    _save("paper_analyses.json", paper_analyses)
    _save("api_keys.json", api_keys)

    return {"data": response, "meta": {"latency_ms": int((time.time() - t0) * 1000)}}

def list_tool_runs(tool_name=None, status=None, api_key_id=None, created_after=None, created_before=None, count=None, offset=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0315000" if __import__("os").path.isdir("./environment_mix/0315000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow()

    api_keys = _load("api_keys.json")
    tool_runs = _load("tool_runs.json")

    # Ambient auth: must have some active key; and the "authenticated workspace" is that key's workspace.
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
    if not active_keys:
        # spec says FORBIDDEN if key revoked, but we have no explicit credential in params.
        # So treat as UNAUTHORIZED when no active key context exists.
        return _err("UNAUTHORIZED", "No active API key available for this request.")
    chosen = sorted(active_keys, key=lambda r: (str(r.get("workspace_id","")), str(r.get("id",""))))[0]
    workspace_id = chosen.get("workspace_id")
    if not workspace_id:
        return _err("UNAUTHORIZED", "API key context could not be resolved.")

    # validate filters
    if tool_name is not None:
        if tool_name not in ("brave_web_search", "brave_local_search", "gemini_research_paper_analysis"):
            return _err("VALIDATION_ERROR", "tool_name is invalid.")
    if status is not None:
        if status not in ("queued", "running", "succeeded", "failed", "cancelled"):
            return _err("VALIDATION_ERROR", "status is invalid.")
    if api_key_id is not None and not isinstance(api_key_id, str):
        return _err("VALIDATION_ERROR", "api_key_id must be a string when provided.")
    if count is None:
        count = 50
    if offset is None:
        offset = 0
    if not isinstance(count, int) or count < 1 or count > 200:
        return _err("VALIDATION_ERROR", "count must be an integer between 1 and 200.")
    if not isinstance(offset, int) or offset < 0:
        return _err("VALIDATION_ERROR", "offset must be a non-negative integer.")

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return "BAD"
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return "BAD"

    ca = _parse_rfc3339(created_after)
    if ca == "BAD":
        return _err("VALIDATION_ERROR", "created_after must be an RFC 3339 timestamp.")
    cb = _parse_rfc3339(created_before)
    if cb == "BAD":
        return _err("VALIDATION_ERROR", "created_before must be an RFC 3339 timestamp.")

    # filter to workspace
    rows = []
    for tr in tool_runs:
        if not isinstance(tr, dict):
            continue
        if tr.get("workspace_id") != workspace_id:
            continue
        if tool_name is not None and tr.get("tool_name") != tool_name:
            continue
        if status is not None and tr.get("status") != status:
            continue
        if api_key_id is not None and tr.get("api_key_id") != api_key_id:
            continue

        # time range
        def _parse_dt(s):
            if not isinstance(s, str):
                return None
            try:
                if s.endswith("Z"):
                    return datetime.datetime.fromisoformat(s[:-1])
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        created = _parse_dt(tr.get("created_at"))
        if ca and created and created < ca:
            continue
        if cb and created and created > cb:
            continue
        if (ca or cb) and created is None:
            continue

        rows.append(tr)

    # newest-first by created_at then id
    def _sort_key(r):
        s = r.get("created_at")
        try:
            if isinstance(s, str) and s.endswith("Z"):
                dt = datetime.datetime.fromisoformat(s[:-1])
            elif isinstance(s, str):
                dt = datetime.datetime.fromisoformat(s)
            else:
                dt = datetime.datetime(1970, 1, 1)
        except Exception:
            dt = datetime.datetime(1970, 1, 1)
        return (dt, str(r.get("id","")))
    rows.sort(key=_sort_key, reverse=True)

    total = len(rows)
    page = rows[offset:offset + count]
    has_more = (offset + count) < total
    next_offset = (offset + count) if has_more else None

    # update chosen last_used_at to reflect successful authenticated read
    now_iso = now.replace(microsecond=0).isoformat() + "Z"
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == chosen.get("id"):
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", api_keys)

    return {
        "data": {
            "runs": page,
            "count": len(page),
            "offset": offset,
            "total": total,
            "has_more": has_more,
            "next_offset": next_offset,
            "workspace_id": workspace_id
        },
        "meta": {"latency_ms": int((time.time() - t0) * 1000)}
    }

def get_tool_run(tool_run_id, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0315000" if __import__("os").path.isdir("./environment_mix/0315000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _sanitize_text(s, max_len=500):
        if s is None:
            return None
        if not isinstance(s, str):
            s = str(s)
        s = s.strip()
        s = re.sub(r"(?i)\b(bearer|api[-_ ]?key|authorization|token|secret|password)\b\s*[:=]\s*[^\s,;]+", r"\1:[REDACTED]", s)
        s = re.sub(r"[A-Za-z0-9_\-]{24,}", "[REDACTED_TOKEN]", s)
        s = re.sub(r"[\w\.-]+@[\w\.-]+\.\w{2,}", "[REDACTED_EMAIL]", s)
        s = re.sub(r"\+?\d[\d \-\(\)]{8,}\d", "[REDACTED_PHONE]", s)
        if len(s) > max_len:
            s = s[:max_len] + "…"
        return s

    def _sanitize_obj(obj, max_str_len=500, max_depth=6):
        if max_depth <= 0:
            return None
        if obj is None:
            return None
        if isinstance(obj, str):
            return _sanitize_text(obj, max_len=max_str_len)
        if isinstance(obj, (int, float, bool)):
            return obj
        if isinstance(obj, list):
            return [_sanitize_obj(v, max_str_len=max_str_len, max_depth=max_depth - 1) for v in obj[:200]]
        if isinstance(obj, dict):
            out = {}
            for k, v in list(obj.items())[:200]:
                kk = str(k)
                if re.search(r"(?i)(authorization|api[-_ ]?key|token|secret|password|cookie)", kk):
                    out[kk] = "[REDACTED]"
                else:
                    out[kk] = _sanitize_obj(v, max_str_len=max_str_len, max_depth=max_depth - 1)
            return out
        return _sanitize_text(obj, max_len=max_str_len)

    def _log(endpoint, api_key_id, status, workspace_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        t1 = time.time()
        row = {
            "id": f"bgr_req_{int(t1*1000)}_{len(logs)+1}",
            "timestamp": _now_iso(),
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "status": status,
            "latency_ms": int(max(0, (t1 - _t0) * 1000)),
        }
        if workspace_id is not None:
            row["workspace_id"] = workspace_id
        if error_code is not None:
            row["error_code"] = error_code
        logs.append(row)
        _save("request_logs.json", logs)

    def _ensure_logs_file():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])

    def _resolve_api_key():
        # Ambient auth: if no explicit credential param, choose any active key in store.
        api_keys = _load("api_keys.json")
        if not isinstance(api_keys, list):
            api_keys = []
        active = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str)]
        if not active:
            revoked = [k for k in api_keys if isinstance(k, dict) and isinstance(k.get("id"), str)]
            if revoked:
                return {"_forbidden": True}
            return None
        active.sort(key=lambda r: (r.get("last_used_at") is None, r.get("last_used_at") or "", r.get("created_at") or ""), reverse=True)
        return active[0]

    _ensure_logs_file()

    if not isinstance(tool_run_id, str) or not tool_run_id.strip():
        _log("get_tool_run", None, "error", error_code="validation_error")
        return _err("VALIDATION_ERROR", "tool_run_id must be a non-empty string")

    api_key = _resolve_api_key()
    if api_key is None:
        _log("get_tool_run", None, "error", error_code="unauthorized")
        return _err("UNAUTHORIZED", "No active API key available to authorize this request")
    if api_key.get("_forbidden"):
        _log("get_tool_run", None, "error", error_code="forbidden")
        return _err("UNAUTHORIZED", "No active API key available to authorize this request")
    if api_key.get("status") == "revoked":
        _log("get_tool_run", api_key.get("id"), "error", error_code="forbidden")
        return _err("UNAUTHORIZED", "API key is revoked")

    tool_runs = _load("tool_runs.json")
    if not isinstance(tool_runs, list):
        tool_runs = []
    run = None
    for r in tool_runs:
        if isinstance(r, dict) and r.get("id") == tool_run_id:
            run = r
            break
    if run is None:
        _log("get_tool_run", api_key.get("id"), "not_found")
        return _err("NOT_FOUND", "Tool run not found")

    workspace_id = run.get("workspace_id")
    if isinstance(workspace_id, str) and api_key.get("workspace_id") != workspace_id:
        # Try to find a key that can authorize this workspace (ambient search)
        api_keys = _load("api_keys.json")
        if not isinstance(api_keys, list):
            api_keys = []
        candidates = [k for k in api_keys if isinstance(k, dict) and k.get("workspace_id") == workspace_id and k.get("status") == "active" and isinstance(k.get("id"), str)]
        if not candidates:
            any_ws = [k for k in api_keys if isinstance(k, dict) and k.get("workspace_id") == workspace_id and isinstance(k.get("id"), str)]
            _log("get_tool_run", api_key.get("id"), "error", workspace_id=workspace_id, error_code="unauthorized")
            if any_ws:
                return _err("UNAUTHORIZED", "No active API key can authorize access to this workspace", workspace_id=workspace_id)
            return _err("NOT_FOUND", "Tool run not found")
        api_key = candidates[0]

    # Update last_used_at on successful authenticated read
    now = _now_iso()
    api_keys_all = _load("api_keys.json")
    if not isinstance(api_keys_all, list):
        api_keys_all = []
    for k in api_keys_all:
        if isinstance(k, dict) and k.get("id") == api_key.get("id"):
            k["last_used_at"] = now
            k["updated_at"] = now
            break
    _save("api_keys.json", api_keys_all)

    # Build response including derived objects
    out_run = {}
    for k, v in run.items():
        if k in ("request_payload", "response_payload"):
            out_run[k] = _sanitize_obj(v)
        elif k in ("error_message",):
            out_run[k] = _sanitize_text(v, max_len=500) if v is not None else None
        else:
            out_run[k] = v

    derived = {}

    if run.get("tool_name") in ("brave_web_search", "brave_local_search"):
        queries = _load("search_queries.json")
        if not isinstance(queries, list):
            queries = []
        qrow = None
        for q in queries:
            if isinstance(q, dict) and q.get("tool_run_id") == tool_run_id:
                qrow = q
                break
        if qrow is not None:
            # list results for query
            results = _load("search_results.json")
            if not isinstance(results, list):
                results = []
            qid = qrow.get("id")
            rrows = [r for r in results if isinstance(r, dict) and r.get("search_query_id") == qid]
            rrows.sort(key=lambda r: (r.get("rank") if isinstance(r.get("rank"), int) else 10**9, r.get("id") or ""))
            derived["search_query"] = _sanitize_obj(qrow)
            derived["search_results"] = [_sanitize_obj(r) for r in rrows]
        else:
            derived["search_query"] = None
            derived["search_results"] = []
    elif run.get("tool_name") == "gemini_research_paper_analysis":
        papers = _load("paper_analyses.json")
        if not isinstance(papers, list):
            papers = []
        prow = None
        for p in papers:
            if isinstance(p, dict) and p.get("tool_run_id") == tool_run_id:
                prow = p
                break
        derived["paper_analysis"] = _sanitize_obj(prow) if prow is not None else None

    resp = {"tool_run": out_run, "derived": derived}
    _log("get_tool_run", api_key.get("id"), "ok", workspace_id=out_run.get("workspace_id"))
    return resp

def cancel_tool_run(tool_run_id, reason=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0315000" if __import__("os").path.isdir("./environment_mix/0315000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _sanitize_reason(s, max_len=200):
        if s is None:
            return None
        if not isinstance(s, str):
            s = str(s)
        s = s.strip()
        s = re.sub(r"(?i)\b(bearer|api[-_ ]?key|authorization|token|secret|password)\b\s*[:=]\s*[^\s,;]+", r"\1:[REDACTED]", s)
        s = re.sub(r"[A-Za-z0-9_\-]{24,}", "[REDACTED_TOKEN]", s)
        s = re.sub(r"[\w\.-]+@[\w\.-]+\.\w{2,}", "[REDACTED_EMAIL]", s)
        s = re.sub(r"\+?\d[\d \-\(\)]{8,}\d", "[REDACTED_PHONE]", s)
        if len(s) > max_len:
            s = s[:max_len] + "…"
        return s

    def _ensure_logs_file():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])

    def _log(endpoint, api_key_id, status, workspace_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        t1 = time.time()
        row = {
            "id": f"bgr_req_{int(t1*1000)}_{len(logs)+1}",
            "timestamp": _now_iso(),
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "status": status,
            "latency_ms": int(max(0, (t1 - _t0) * 1000)),
        }
        if workspace_id is not None:
            row["workspace_id"] = workspace_id
        if error_code is not None:
            row["error_code"] = error_code
        logs.append(row)
        _save("request_logs.json", logs)

    def _resolve_api_key_for_workspace(workspace_id):
        api_keys = _load("api_keys.json")
        if not isinstance(api_keys, list):
            api_keys = []
        active = [k for k in api_keys if isinstance(k, dict) and k.get("workspace_id") == workspace_id and k.get("status") == "active" and isinstance(k.get("id"), str)]
        if active:
            return active[0]
        any_keys = [k for k in api_keys if isinstance(k, dict) and k.get("workspace_id") == workspace_id and isinstance(k.get("id"), str)]
        if any_keys:
            return {"_revoked_only": True}
        return None

    _ensure_logs_file()

    if not isinstance(tool_run_id, str) or not tool_run_id.strip():
        _log("cancel_tool_run", None, "error", error_code="validation_error")
        return _err("VALIDATION_ERROR", "tool_run_id must be a non-empty string")

    if reason is not None and not isinstance(reason, str):
        _log("cancel_tool_run", None, "error", error_code="validation_error")
        return _err("VALIDATION_ERROR", "reason must be a string when provided")

    tool_runs = _load("tool_runs.json")
    if not isinstance(tool_runs, list):
        tool_runs = []
    idx = None
    run = None
    for i, r in enumerate(tool_runs):
        if isinstance(r, dict) and r.get("id") == tool_run_id:
            idx = i
            run = r
            break
    if run is None:
        _log("cancel_tool_run", None, "not_found")
        return _err("NOT_FOUND", "Tool run not found")

    workspace_id = run.get("workspace_id")
    api_key = _resolve_api_key_for_workspace(workspace_id) if isinstance(workspace_id, str) else None
    if api_key is None:
        _log("cancel_tool_run", None, "error", workspace_id=workspace_id, error_code="unauthorized")
        return _err("UNAUTHORIZED", "No API key in the datastore can authorize access to this workspace", workspace_id=workspace_id)
    if api_key.get("_revoked_only"):
        _log("cancel_tool_run", None, "error", workspace_id=workspace_id, error_code="forbidden")
        return _err("UNAUTHORIZED", "API key for this workspace is revoked", workspace_id=workspace_id)

    # Terminal states: return unchanged (idempotent)
    if run.get("status") in ("succeeded", "failed", "cancelled"):
        # Update last_used_at for the workspace key (successful auth)
        now = _now_iso()
        api_keys_all = _load("api_keys.json")
        if not isinstance(api_keys_all, list):
            api_keys_all = []
        for k in api_keys_all:
            if isinstance(k, dict) and k.get("id") == api_key.get("id"):
                k["last_used_at"] = now
                k["updated_at"] = now
                break
        _save("api_keys.json", api_keys_all)

        _log("cancel_tool_run", api_key.get("id"), "ok", workspace_id=workspace_id)
        return {"tool_run": run}

    # Only queued/running may transition to cancelled
    if run.get("status") not in ("queued", "running"):
        _log("cancel_tool_run", api_key.get("id"), "error", workspace_id=workspace_id, error_code="invalid_transition")
        return _err("INVALID_TRANSITION", f"Cannot cancel tool run from status '{run.get('status')}'")

    now = _now_iso()
    run = dict(run)
    run["status"] = "cancelled"
    run["completed_at"] = now
    run["updated_at"] = now
    # Persist sanitized cancellation reason into error_message (allowed nullable string) without PII
    sreason = _sanitize_reason(reason)
    if sreason:
        run["error_code"] = "cancelled"
        run["error_message"] = sreason
    else:
        run["error_code"] = run.get("error_code") or "cancelled"
        run["error_message"] = run.get("error_message")

    tool_runs[idx] = run
    _save("tool_runs.json", tool_runs)

    # Update api_key usage marker
    api_keys_all = _load("api_keys.json")
    if not isinstance(api_keys_all, list):
        api_keys_all = []
    for k in api_keys_all:
        if isinstance(k, dict) and k.get("id") == api_key.get("id"):
            k["last_used_at"] = now
            k["updated_at"] = now
            break
    _save("api_keys.json", api_keys_all)

    _log("cancel_tool_run", api_key.get("id"), "ok", workspace_id=workspace_id)
    return {"tool_run": run}

