        _log("list_search_results", None, "error", error_code="validation_error")
        return _err("VALIDATION_ERROR", "count must be an integer between 1 and 200")
    if not isinstance(offset, int) or offset < 0:
        _log("list_search_results", None, "error", error_code="validation_error")
        return _err("VALIDATION_ERROR", "offset must be an integer >= 0")

    # tool parameter uses enum web/local (not storage enum); map local -> local_place, web -> web
    storage_result_type = None
    if result_type is not None:
        if not isinstance(result_type, str):
            _log("list_search_results", None, "error", error_code="validation_error")
            return _err("VALIDATION_ERROR", "result_type must be a string when provided")
