    # Resolve workspace via tool_run
    tool_runs = _load("tool_runs.json")
    if not isinstance(tool_runs, list):
        tool_runs = []
    run = None
    for r in tool_runs:
        if isinstance(r, dict) and r.get("id") == qrow.get("tool_run_id"):
            run = r
            break
    if run is None:
        # Broken FK in store; treat as NOT_FOUND in caller scope
        _log("list_search_results", None, "error", error_code="not_found")
        return _err("NOT_FOUND", "Search query not found")

    workspace_id = run.get("workspace_id")
    api_key = _resolve_api_key_for_workspace(workspace_id) if isinstance(workspace_id, str) else None
    if api_key is None:
        _log("list_search_results", None, "error", workspace_id=workspace_id, error_code="unauthorized")
