    results = _load("search_results.json")
    if not isinstance(results, list):
        results = []
    rows = [r for r in results if isinstance(r, dict) and r.get("search_query_id") == search_query_id]
    if storage_result_type is not None:
        rows = [r for r in rows if r.get("result_type") == storage_result_type]
    rows.sort(key=lambda r: (r.get("rank") if isinstance(r.get("rank"), int) else 10**9, r.get("id") or ""))

    total = len(rows)
    page = rows[offset: offset + count]
    has_more = offset + count < total
    next_cursor = offset + count if has_more else None

    # Update api key last_used_at (successful authenticated read)
    now = _now_iso()
    api_keys_all = _load("api_keys.json")
    if not isinstance(api_keys_all, list):
        api_keys_all = []
    for k in api_keys_all:
