            k["last_used_at"] = now
            k["updated_at"] = now
            break
    _save("api_keys.json", api_keys_all)

    _log("list_search_results", api_key.get("id"), "ok", workspace_id=workspace_id)
    return {
        "search_query_id": search_query_id,
        "results": page,
        "pagination": {
            "count": count,
            "offset": offset,
            "total": total,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

def revoke_api_key(api_key_id=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0315000" if __import__("os").path.isdir("./environment_mix/0315000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _get_ambient_key(api_keys):
        for k in api_keys:
            if isinstance(k, dict) and k.get("status") == "active":
                return k
        return None

    t0 = time.time()
    status_for_log = "failed"
    used_key_id = None
    try:
        if api_key_id is not None and (not isinstance(api_key_id, str) or not api_key_id.strip()):
            return _err("VALIDATION_ERROR", "api_key_id must be a non-empty string when provided")

        api_keys = _load("api_keys.json")
        caller = _get_ambient_key(api_keys)
        if not caller:
            return _err("UNAUTHORIZED", "API key is missing or invalid")
        used_key_id = caller.get("id")

        if caller.get("status") == "revoked":
            return _err("FORBIDDEN", "API key is revoked")

        target_id = api_key_id or caller.get("id")
        ws = caller.get("workspace_id")

        tgt_idx = None
        for i, k in enumerate(api_keys):
            if isinstance(k, dict) and k.get("id") == target_id:
                tgt_idx = i
                break
        if tgt_idx is None:
            return _err("NOT_FOUND", "API key not found")

        target = api_keys[tgt_idx]
        # Permission: only keys in same workspace
        if target.get("workspace_id") != ws:
            return _err("FORBIDDEN", "Not permitted to revoke this API key")

        if target.get("status") == "revoked":
            return _err("FORBIDDEN", "API key is already revoked")

        if target.get("status") != "active":
            return _err("INVALID_TRANSITION", f"Cannot revoke from status '{target.get('status')}'")

        now = _now_iso()
        target["status"] = "revoked"
        target["updated_at"] = now
        api_keys[tgt_idx] = target
        _save("api_keys.json", api_keys)

        # Update caller last_used_at as this was a successful authenticated request
        caller["last_used_at"] = now
        caller["updated_at"] = now
        # caller is a dict reference into api_keys only if it was the same object; ensure persisted already above.

        status_for_log = "succeeded"
        return {"api_key": target}
    finally:
        _ = t0, used_key_id, status_for_log
